def current_display_spelling(value):
    if isinstance(value, str):
        return CORRECTIONS.get(value, value)
    if isinstance(value, list):
        return [current_display_spelling(item) for item in value]
    if isinstance(value, dict):
        return {key: item if key in {'source_code', 'line_text', 'caller_source_code'}
                else current_display_spelling(item) for key, item in value.items()}
    return value
